from mnk.money import VAT_PERCENT


def vat_part_cents(net_items: list[int]) -> int:
    """Total VAT in cents. Each line's VAT is 16% of its net amount, rounded down to the cent (as in add_vat)."""
    return sum(n * VAT_PERCENT // 100 for n in net_items)

