from mnk.delivery import delivery_fee_kes, zone_of

def zone_fees(areas_km: dict[str, float]) -> dict[str, int]:
    out = {}
    for area, km in areas_km.items():
        if zone_of(area) == 'X':
            out[area] = -1
        else:
            out[area] = delivery_fee_kes(round(km * 1000))  # helpers take metres
    return out
